 useEffect(()=>{Animated.sequence([Animated.timing(splashOpacity,{toValue:1,duration:1600,useNativeDriver:true}),Animated.timing(splashOptionsOpacity,{toValue:1,duration:750,useNativeDriver:true})]).start();},[]);
 useEffect(()=>{(async()=>{try{const raw=await AsyncStorage.getItem('demoAccount'); const p=await AsyncStorage.getItem('demoCompleted');const t=await AsyncStorage.getItem('demoTasks'); if(raw)setAccount(JSON.parse(raw));const fav=await AsyncStorage.getItem('demoFavoriteMatches');if(fav)setMatchFavorites(JSON.parse(fav));const alerts=await AsyncStorage.getItem('demoMatchAlertPreference');if(alerts)setNotificationsWanted(JSON.parse(alerts));const c=await AsyncStorage.getItem('demoContacts');if(c)setContacts(JSON.parse(c));const mn=await AsyncStorage.getItem('demoMatchNotes');if(mn)setMatchNotes(JSON.parse(mn));const sm=await AsyncStorage.getItem('demoOrgStructure');if(sm)setStructureMembers(JSON.parse(sm));const shopData=await AsyncStorage.getItem('demoMerchCatalog');if(shopData)setMerch(JSON.parse(shopData));const fameData=await AsyncStorage.getItem('demoHallOfFame');if(fameData)setFame(JSON.parse(fameData));const noticesStored=await AsyncStorage.getItem('demoNotices');if(noticesStored)setNotices(JSON.parse(noticesStored));const rsvpStored=await AsyncStorage.getItem('demoRsvp');if(rsvpStored)setRsvp(JSON.parse(rsvpStored));const messagesStored=await AsyncStorage.getItem('demoChatMessages');if(messagesStored)setMessages(JSON.parse(messagesStored));const pd=await AsyncStorage.getItem('demoPlayerDetails');if(pd)setPlayerDetails(JSON.parse(pd));const bm=await AsyncStorage.getItem('demoCoachBenchmarks');if(bm)setBenchmarks(JSON.parse(bm));const at=await AsyncStorage.getItem('demoAttendanceDates');if(at)setAttendance(JSON.parse(at));const ack=await AsyncStorage.getItem('regulationAcknowledgements');if(ack)setDocumentAcks(JSON.parse(ack));if(p)setCompleted(JSON.parse(p));if(t)setChecked(JSON.parse(t));const lp=await AsyncStorage.getItem('playerLevelProgress');if(lp)setLevelProgress(JSON.parse(lp));const ep=await AsyncStorage.getItem('playerExerciseChecks');if(ep)setExerciseChecks(JSON.parse(ep));}finally{setBusy(false);}})()},[]);
 async function savePlayerDetails(p:typeof playerDetails){setPlayerDetails(p);await AsyncStorage.setItem('demoPlayerDetails',JSON.stringify(p));}
 async function saveBenchmarks(p:typeof benchmarks){if(account?.role!=='coach')return;setBenchmarks(p);await AsyncStorage.setItem('demoCoachBenchmarks',JSON.stringify(p));}
 async function addAttendance(){if(account?.role!=='coach'||!/^\d{4}-\d{2}-\d{2}$/.test(trainingDate)||Number.isNaN(Date.parse(trainingDate)))return;const next=[...new Set([...attendance,trainingDate])].sort().reverse();setAttendance(next);setTrainingDate('');await AsyncStorage.setItem('demoAttendanceDates',JSON.stringify(next));}
 async function publishNotice(){if(!account||!['coach','aup'].includes(account.role)||!noticeDate.trim()||!noticeText.trim())return;const next=[{id:String(Date.now()),date:noticeDate.trim(),message:noticeText.trim()},...notices];setNotices(next);setNoticeDate('');setNoticeText('');await AsyncStorage.setItem('demoNotices',JSON.stringify(next));}
 async function setAttendanceAnswer(id:string,answer:'yes'|'no'){const next={...rsvp,[id]:{answer,comment:rsvp[id]?.comment||''}};setRsvp(next);await AsyncStorage.setItem('demoRsvp',JSON.stringify(next));}
 async function updateAttendanceComment(id:string,comment:string){const next={...rsvp,[id]:{answer:'no' as const,comment}};setRsvp(next);await AsyncStorage.setItem('demoRsvp',JSON.stringify(next));}
 async function sendChat(channel:'team'|'recruit'){if(!account||!chatText.trim())return;const next=[...messages,{id:String(Date.now()),channel,author:account.name,text:chatText.trim()}];setMessages(next);setChatText('');await AsyncStorage.setItem('demoChatMessages',JSON.stringify(next));}
 async function addMerch(){if(!account||!['coach','aup'].includes(account.role)||!merchDraft.title.trim()||!merchDraft.price.trim())return;const next=[{id:String(Date.now()),...merchDraft},...merch];setMerch(next);await AsyncStorage.setItem('demoMerchCatalog',JSON.stringify(next));setMerchDraft({title:'',price:'',description:''});}
 async function addFame(){if(!account||!['coach','aup'].includes(account.role)||!fameDraft.name.trim())return;const next=[{id:String(Date.now()),...fameDraft},...fame];setFame(next);await AsyncStorage.setItem('demoHallOfFame',JSON.stringify(next));setFameDraft({name:'',position:'',award:'MVP',stats:''});}
 async function addContact(){if(!['coach','aup'].includes(account?.role||'')||!contactDraft.name.trim())return;const next=[...contacts,contactDraft];setContacts(next);await AsyncStorage.setItem('demoContacts',JSON.stringify(next));setContactDraft({name:'',phone:'',address:'',telegram:'',contactPerson:''});}
 async function addMatchNote(){if(account?.role!=='coach'||!matchDraft.player.trim()||!matchDraft.match.trim())return;const next=[...matchNotes,matchDraft];setMatchNotes(next);await AsyncStorage.setItem('demoMatchNotes',JSON.stringify(next));setMatchDraft({player:'',match:'',position:'',gameMinutes:'',trainingMinutes:''});}
 async function addStructureMember(){if(!['coach','aup'].includes(account?.role||'')||!structureDraft.name.trim()||!structureDraft.role.trim())return;const next=[...structureMembers,structureDraft];setStructureMembers(next);await AsyncStorage.setItem('demoOrgStructure',JSON.stringify(next));setStructureDraft({name:'',role:'',photo:''});}
 async function toggleMatchFavorite(id:string){const next=matchFavorites.includes(id)?matchFavorites.filter(x=>x!==id):[...matchFavorites,id];setMatchFavorites(next);await AsyncStorage.setItem('demoFavoriteMatches',JSON.stringify(next));}
 async function toggleMatchAlerts(){const next=!notificationsWanted;setNotificationsWanted(next);await AsyncStorage.setItem('demoMatchAlertPreference',JSON.stringify(next));}
 async function saveAccount(a:Account|null){setAccount(a);if(a) await AsyncStorage.setItem('demoAccount',JSON.stringify(a)); else await AsyncStorage.removeItem('demoAccount');}
 const exerciseList=(value:string)=>value.split(',').map(x=>x.trim()).filter(Boolean);
 const dayDone=(dayId:number,exerciseNames:string[])=>levelProgress.includes(dayId)||exerciseNames.every((_,i)=>exerciseChecks.includes(dayId+':'+i));
 async function toggleExercise(dayId:number,index:number,count:number){
  const key=dayId+':'+index;
  const next=levelProgress.includes(dayId)?[...exerciseChecks.filter(x=>!x.startsWith(dayId+':')),...Array.from({length:count},(_,i)=>dayId+':'+i).filter(x=>x!==key)]:exerciseChecks.includes(key)?exerciseChecks.filter(x=>x!==key):[...exerciseChecks,key];
  if(levelProgress.includes(dayId)){const days=levelProgress.filter(x=>x!==dayId);setLevelProgress(days);await AsyncStorage.setItem('playerLevelProgress',JSON.stringify(days));}
  setExerciseChecks(next);await AsyncStorage.setItem('playerExerciseChecks',JSON.stringify(next));
 }
 async function acknowledgeSection(key:string){const next=[...new Set([...documentAcks,key])];setDocumentAcks(next);await AsyncStorage.setItem('regulationAcknowledgements',JSON.stringify(next));}
 const docInput=(label:string,key:keyof typeof identity,placeholder:string,keyboardType:'default'|'numeric'='default')=><View style={{gap:5}}><Text style={styles.overline}>{label}</Text><TextInput style={styles.input} value={identity[key]} onChangeText={v=>updateIdentity(key,v)} placeholder={placeholder} placeholderTextColor="#888" keyboardType={keyboardType}/></View>;
 const documentContent=(withForm=false)=> <View style={{gap:15}}>
  <Text style={styles.hero}>{regulationTitle}</Text>
  <Text style={styles.muted}>Разделы 1-6 регламента. Демоверсия: указывай только вымышленные сведения. Паспортные данные не отправляются на сервер и не сохраняются в браузере. Эта форма не заменяет юридическую подпись.</Text>
  {regulationSections.map((section,i)=><View key={i} style={styles.infoCard}><Text style={styles.entryRole}>{section.heading}</Text>
   {withForm&&i===0?<><Text style={styles.body}>г. Москва</Text>{docInput('ФИО ПОЛНОСТЬЮ','fullName','Пример: Иванов Иван Иванович')}{docInput('СЕРИЯ ПАСПОРТА','passportSeries','0000','numeric')}{docInput('НОМЕР ПАСПОРТА','passportNumber','000000','numeric')}{docInput('КЕМ ВЫДАН','passportIssuedBy','Наименование органа')}{docInput('ДАТА ВЫДАЧИ','passportIssuedDate','ДД.ММ.ГГГГ')}{docInput('АДРЕС РЕГИСТРАЦИИ','address','Адрес') }<Text style={styles.muted}>Эти поля соответствуют местам для заполнения в вводной части документа.</Text></>:
    section.items.map((line,j)=><Text key={j} style={styles.body}>{line}</Text>)}
  </View>)}
 </View>;
 async function toggleCompleted(id:number){const next=completed.includes(id)?completed.filter(x=>x!==id):[...completed,id];setCompleted(next);await AsyncStorage.setItem('demoCompleted',JSON.stringify(next));}
