 const Button=({label,click,outline=false}:{label:string;click:()=>void;outline?:boolean})=><TouchableOpacity style={[styles.button,outline&&styles.outline]} onPress={click}><Text style={[styles.buttonText,outline&&{color:GOLD}]}>{label}</Text></TouchableOpacity>;
