  {screen==='lesson'&&<><TouchableOpacity onPress={()=>navigate('course')}><Text style={styles.gold}>‹ Все занятия</Text></TouchableOpacity><Text style={styles.hero}>ЗАНЯТИЕ {selected.id}</Text><Heading>{selected.title}</Heading><Chip text={`НЕДЕЛЯ ${selected.week} · 90 МИН`}/><View style={styles.card}><Text style={styles.gold}>ЗАДАЧА ЗАНЯТИЯ</Text><Text style={styles.body}>{selected.objective}</Text><Text style={styles.muted}>Бесконтактный формат. Полный тайминг, дозировки и схемы приведены в исходном PDF.</Text><Heading>Упражнения по программе</Heading><Text style={styles.body}>{selected.exerciseCodes.join('  ·  ')}</Text><Button label="Открыть полный план (PDF)" outline click={sharePdf}/></View><Button label={completed.includes(selected.id)?'Отменить демо-отметку':'Демо: отметить пройденным'} click={()=>toggleCompleted(selected.id)}/><Text style={styles.muted}>Отметка сохраняется только на этом устройстве; в рабочей версии тренер подтверждает прохождение на сервере.</Text></>}
