 {attendance.length===0?<Text style={styles.muted}>Даты посещений пока не внесены.</Text>:attendance.map(date=><View key={date} style={styles.trainingRow}><Text style={[styles.body,{flex:1}]}>{date}</Text>{account.role==='coach'&&<TouchableOpacity onPress={async()=>{const next=attendance.filter(d=>d!==date);setAttendance(next);await AsyncStorage.setItem('demoAttendanceDates',JSON.stringify(next))}}><Text style={styles.gold}>УДАЛИТЬ</Text></TouchableOpacity>}</View>)}
